console.log(`9007199254740993 prints as ${9007199254740993}`);
console.log(`isSafeInteger(2 ** 53 - 1): ${Number.isSafeInteger(2 ** 53 - 1)}`);
console.log(`isSafeInteger(2 ** 53): ${Number.isSafeInteger(2 ** 53)}`);

let n = 1;
let prev = 0;
let curr = 1;
while (Number.isSafeInteger(prev + curr)) {
  const next = prev + curr;
  prev = curr;
  curr = next;
  n++;
}
console.log(`F(${n}) = ${curr} is the last safe Fibonacci number`);

