const text = "123456789012345678901234567890";

let prev = 0n;
let curr = 1n;
for (let i = 2; i <= 100; i++) {
  const next = prev + curr;
  prev = curr;
  curr = next;
}
console.log(`F(100) = ${curr}`);

console.log(`10n % 3n = ${10n % 3n}`);
